// serviceStatusHandler returns the additive, public service status contract.
// HTTP status is the primary availability signal; the body status refines it.
// Build metadata is intentionally excluded until an authenticated metadata
// extension can be wired without exposing deployment details publicly.
func serviceStatusHandler(w http.ResponseWriter, _ *http.Request) {
	status := serviceStatusProvider()
	respondJSON(w, serviceStatusHTTPCode(status), ServiceStatusResponse{
		Status:  status,
		Service: "metadata-service",
	})
}

func serviceStatusHTTPCode(status ServiceStatus) int {
	switch status {
	case ServiceStatusOK, ServiceStatusDegraded:
		return http.StatusOK
	case ServiceStatusDown, ServiceStatusInitializing:
		return http.StatusServiceUnavailable
	default:
		return http.StatusServiceUnavailable
	}
}

